package gadomancymodern.test;
import gadomancymodern.Gadomancy;
import gadomancymodern.disguise.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.*;
import tc4revival.content.*;

@GameTestHolder("gadomancy") @PrefixGameTestTemplate(false)
public class DisguiseServerTests {
    protected static java.util.List<ItemStack> components(ItemStack disguise){var mercury=TCItems.material(MaterialType.QUICKSILVER);return java.util.List.of(new ItemStack(Items.SLIME_BALL),new ItemStack(mercury),disguise,new ItemStack(mercury),new ItemStack(Items.SLIME_BALL));}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void infusionChecksSlotResearchAndPersistsSelectedAppearance(GameTestHelper test){
        var level=test.getLevel();var recipe=(DisguiseInfusion)level.getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("gadomancy:armor_disguise")).orElseThrow();var center=new ItemStack(Items.DIAMOND_CHESTPLATE);center.setDamageValue(50);center.enchant(net.minecraft.world.item.enchantment.Enchantments.ALL_DAMAGE_PROTECTION,3);center.getOrCreateTag().getCompound("gadomancy").putString("other","preserved");var other=new net.minecraft.nbt.CompoundTag();other.putString("other","preserved");center.getOrCreateTag().put("gadomancy",other);var disguise=new ItemStack(Items.LEATHER_CHESTPLATE);((DyeableLeatherItem)disguise.getItem()).setColor(disguise,0x123456);disguise.setHoverName(net.minecraft.network.chat.Component.literal("Disguise"));
        test.assertTrue(!recipe.matches(new InfusionRecipe.Input(center,components(disguise),key->false),level),"No research cannot disguise armor");test.assertTrue(!recipe.matches(new InfusionRecipe.Input(center,components(new ItemStack(Items.LEATHER_BOOTS)),key->true),level),"Different armor slots reject the entire infusion");test.assertTrue(recipe.matches(new InfusionRecipe.Input(center,components(disguise),key->true),level),"Damaged enchanted center and dyed named same-slot armor match");var plan=recipe.planForCraft(center,level);test.assertTrue(plan.instability()==-20&&plan.aspects().total()==30&&plan.components().size()==5,"Old negative instability and all five pedestal costs retained");var output=InfusionOutput.load(plan.output().save()).apply(center);test.assertTrue(ItemStack.isSameItemSameTags(ArmorDisguise.appearance(output),disguise)&&output.getDamageValue()==50&&net.minecraft.world.item.enchantment.EnchantmentHelper.getItemEnchantmentLevel(net.minecraft.world.item.enchantment.Enchantments.ALL_DAMAGE_PROTECTION,output)==3,"Saved infusion transaction preserves real armor stats and exact visual armor NBT");test.assertTrue(!recipe.matches(new InfusionRecipe.Input(output,components(disguise),key->true),level),"Cannot overwrite existing disguise");var returned=ArmorDisguise.remove(output);test.assertTrue(ItemStack.isSameItemSameTags(returned,disguise)&&ItemStack.isSameItemSameTags(output,center),"Removing disguise restores exact armor and returns visual armor");
        var buffer=new net.minecraft.network.FriendlyByteBuf(io.netty.buffer.Unpooled.buffer());Gadomancy.DISGUISE_RECIPE.get().toNetwork(buffer,recipe);var synced=Gadomancy.DISGUISE_RECIPE.get().fromNetwork(recipe.getId(),buffer);test.assertTrue(synced.matches(new InfusionRecipe.Input(center,components(disguise),key->true),level),"Custom ingredient survives recipe synchronization");buffer.release();test.succeed();
    }
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void invisibilityAndStackedSkullDoNotDuplicateDisguises(GameTestHelper test){
        var helmet=new ItemStack(Items.IRON_HELMET);var skull=new ItemStack(Items.SKELETON_SKULL,64);test.assertTrue(ArmorDisguise.valid(helmet,skull),"Original head-slot disguise includes skulls");var output=ArmorDisguise.apply(helmet,skull);test.assertTrue(ArmorDisguise.remove(output).getCount()==1&&skull.getCount()==64,"One consumed pedestal unit yields only one returned disguise even for a stacked skull");
        for(var item:java.util.List.of(Items.POTION,Items.SPLASH_POTION))for(var potion:java.util.List.of(net.minecraft.world.item.alchemy.Potions.INVISIBILITY,net.minecraft.world.item.alchemy.Potions.LONG_INVISIBILITY)){var drink=net.minecraft.world.item.alchemy.PotionUtils.setPotion(new ItemStack(item),potion);test.assertTrue(ArmorDisguise.valid(helmet,drink),"All four legacy invisibility potion variants match");output=ArmorDisguise.apply(helmet,drink);test.assertTrue(ArmorDisguise.disguised(output)&&ArmorDisguise.appearance(output).isEmpty()&&ArmorDisguise.remove(output).isEmpty()&&ItemStack.isSameItemSameTags(output,helmet),"Invisible armor cleans without refunding a consumed potion");}test.succeed();
    }
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void cleansingRequiresExpiredDelayAndPureSource(GameTestHelper test){
        var level=test.getLevel();var pos=test.absolutePos(new BlockPos(3,8,3));var disguise=new ItemStack(Items.GOLDEN_CHESTPLATE);var armor=ArmorDisguise.apply(new ItemStack(Items.IRON_CHESTPLATE),disguise);var item=new net.minecraft.world.entity.item.ItemEntity(level,pos.getX()+.5,pos.getY()+.25,pos.getZ()+.5,armor);item.setNoPickUpDelay();item.setNoGravity(true);level.addFreshEntity(item);
        level.setBlockAndUpdate(pos,TCCleansing.PURE_WATER.get().defaultBlockState());DisguiseCleansing.advance(item,level.getGameTime()+40);test.assertTrue(ArmorDisguise.disguised(item.getItem()),"Cannot cleanse before delay");level.setBlockAndUpdate(pos,TCCleansing.PURE_WATER.get().defaultBlockState().setValue(net.minecraft.world.level.block.LiquidBlock.LEVEL,1));DisguiseCleansing.advance(item,-1);test.assertTrue(ArmorDisguise.disguised(item.getItem()),"Flowing pure water cannot cleanse");level.setBlockAndUpdate(pos,TCCleansing.PURE_WATER.get().defaultBlockState());item.setPickUpDelay(1);DisguiseCleansing.advance(item,-1);test.assertTrue(ArmorDisguise.disguised(item.getItem()),"Pickup delay also gates cleansing");item.setNoPickUpDelay();DisguiseCleansing.advance(item,-1);test.assertTrue(!ArmorDisguise.disguised(item.getItem())&&level.isEmptyBlock(pos),"Expired item consumes exactly the pure source and synchronizes new stack");var refunds=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(1),e->e.getItem().is(Items.GOLDEN_CHESTPLATE));test.assertTrue(refunds.size()==1&&refunds.get(0).getItem().getCount()==1,"The visual armor is returned once");DisguiseCleansing.advance(item,-1);test.assertTrue(level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(1),e->e.getItem().is(Items.GOLDEN_CHESTPLATE)).size()==1,"Repeated tick cannot duplicate refund");test.succeed();
    }
}
